(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-875":{scenario:{company:"Trường Đại học Công nghệ Bắc Hà",supervisor:{name:"Lê Minh Khoa",role:{vi:"Trưởng phòng Công tác Sinh viên",en:"Head of Student Affairs"}},ref_code:"SV-2381",title:{vi:"Đúng quy chế. Đúng học bổng. Công bằng cho người học.",en:"Right rules. Right scholarship. Fair to every student."},brief:{vi:"Bạn rà soát hồ sơ xét học bổng khuyến khích học tập học kỳ I của sinh viên mã SV-2381: điểm trung bình học kỳ 3.45/4, điểm rèn luyện 79/100. Mức học bổng mô phỏng mỗi tháng: HB-A 2000000, HB-B 1700000, HB-C 1450000 đồng; học kỳ tính 5 tháng. Đối chiếu bản nháp với quy chế đã duyệt, sửa loại học bổng và tổng tiền học kỳ, rồi lập báo cáo có căn cứ.",en:"You are reviewing the semester 1 merit scholarship file of student SV-2381: semester GPA 3.45/4, conduct score 79/100. Training monthly rates: HB-A 2000000, HB-B 1700000, HB-C 1450000 VND; a semester counts as 5 months. Compare the draft with the approved regulation, correct the scholarship tier and the semester total, then write an evidence-based report."},reference_title:{vi:"Quy chế học bổng & biên bản hội đồng đã duyệt · SV-2381",en:"Approved scholarship regulation & committee minutes · SV-2381"},fields:[{id:"SCH_TIER",label:{vi:"Loại học bổng",en:"Scholarship tier"},initial:"HB-B",expected:"HB-C",choices:["HB-A","HB-B","HB-C"],reference:"Quy chế học bổng mục 2",hint:{vi:"Loại học bổng phải thỏa đồng thời điều kiện học tập và rèn luyện; 79 điểm rèn luyện chưa đạt mức tốt.",en:"The tier must meet both academic and conduct conditions; a conduct score of 79 is below the good band."}},{id:"SCH_TOTAL",label:{vi:"Tổng học bổng học kỳ (đồng)",en:"Semester scholarship total (VND)"},initial:"8500000",expected:"7250000",reference:"Bảng mức học bổng học kỳ I",ref_value:{vi:"Mức tháng: HB-A 2000000, HB-B 1700000, HB-C 1450000 đồng; học kỳ 5 tháng (mô phỏng)",en:"Monthly: HB-A 2000000, HB-B 1700000, HB-C 1450000 VND; 5-month semester (training)"},hint:{vi:"Xác định đúng loại học bổng trước, rồi mới nhân mức tháng với số tháng của học kỳ.",en:"Fix the tier first, then multiply its monthly rate by the semester months."}}],sop32:{vi:"HB-A: học tập 3.6-4.0 và rèn luyện 90-100; HB-B: học tập từ 3.2 và rèn luyện từ 80; HB-C: học tập từ 2.5 và rèn luyện từ 65. Phải đạt cả hai điều kiện; tổng học kỳ = mức tháng x 5 tháng (mô phỏng).",en:"HB-A: GPA 3.6-4.0 and conduct 90-100; HB-B: GPA from 3.2 and conduct from 80; HB-C: GPA from 2.5 and conduct from 65. Both conditions must be met; semester total = monthly rate x 5 months (training)."},context:{label:"HỒ SƠ XÉT HỌC BỔNG / SV-2381",metrics:[{label:{vi:"Điểm TB học kỳ",en:"Semester GPA"},value:"3.45 / 4"},{label:{vi:"Điểm rèn luyện",en:"Conduct score"},value:"79 / 100"},{label:{vi:"Số tháng học kỳ",en:"Semester months"},value:"5"}]},crisis:{vi:"Cố vấn học tập của lớp nhắn: “Cộng thêm 1 điểm rèn luyện cho em ấy lên 80 đi, gia đình khó khăn, chênh có 1 điểm, hội đồng không soát lại đâu.”",en:"The class academic advisor texts: “Just add 1 conduct point so the student reaches 80. The family is struggling, it is only 1 point and the committee will not recheck.”"},options:{safe:{vi:"Giữ đúng 79 điểm theo biên bản đã duyệt, báo Trưởng phòng; hướng dẫn sinh viên phúc khảo nếu có minh chứng và giới thiệu chính sách hỗ trợ sinh viên khó khăn.",en:"Keep the approved 79 points and inform the Head of Student Affairs; guide the student to appeal with evidence and refer them to hardship support."},shortcut:{vi:"Sửa điểm rèn luyện lên 80 để sinh viên nhận HB-B, coi như giúp đỡ hoàn cảnh khó khăn.",en:"Change the conduct score to 80 so the student gets HB-B, as a favor for a hardship case."},wait:{vi:"Giữ hồ sơ lại, không trả lời cố vấn và chờ hội đồng tự phát hiện sai lệch.",en:"Hold the file, ignore the advisor and wait for the committee to spot the error."}},questions:{vi:["Vì sao sinh viên SV-2381 thuộc loại HB-C chứ không phải HB-B? Dẫn chứng bằng điểm và điều kiện của quy chế.","Trình bày cách tính tổng học bổng học kỳ và cách bạn hỗ trợ sinh viên khó khăn mà vẫn bảo đảm công bằng."],en:["Why is student SV-2381 in tier HB-C rather than HB-B? Cite the scores and the regulation conditions.","Explain how you calculated the semester total and how you would support a struggling student while staying fair."]},hints:{vi:["Đặt điểm học tập và điểm rèn luyện cạnh bảng điều kiện từng loại, đánh dấu điều kiện chưa đạt.","Lấy đúng mức tháng của loại học bổng đã sửa rồi nhân số tháng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không sửa điểm đã được hội đồng phê duyệt; mọi đề nghị phải đi qua phúc khảo."],en:["Put the GPA and conduct score next to each tier's conditions and flag the unmet one.","Take the monthly rate of the corrected tier and multiply by the months in SOP 3.2.","Re-read SOP 4.2: approved scores are never edited; every request goes through the appeal process."]}},learning:{summary:{vi:"Chuyên viên công tác sinh viên và hướng nghiệp đồng hành cùng người học trong suốt quá trình học: đánh giá rèn luyện, xét học bổng và chế độ chính sách, tư vấn học đường, hướng nghiệp, kết nối thực tập và việc làm, khảo sát việc làm sau tốt nghiệp. Nghề đòi hỏi am hiểu quy chế, công bằng, bảo mật thông tin và kỹ năng tư vấn lấy người học làm trung tâm.",en:"A student affairs and career guidance officer supports learners throughout their studies: conduct assessment, scholarships and welfare policies, student counseling, career guidance, internship and job matching, and graduate employment surveys. The role requires solid knowledge of regulations, fairness, data confidentiality and student-centered counseling skills."},responsibilities:{vi:["Tổ chức đánh giá kết quả rèn luyện, xét học bổng, miễn giảm học phí và trợ cấp theo quy chế.","Tư vấn học tập, tâm lý học đường và hướng nghiệp cá nhân, nhóm cho sinh viên.","Kết nối doanh nghiệp, tổ chức ngày hội việc làm và quản lý chương trình thực tập.","Khảo sát tình hình việc làm của sinh viên tốt nghiệp và lập báo cáo phục vụ kiểm định.","Quản lý hồ sơ sinh viên, xử lý vi phạm theo quy trình và bảo mật dữ liệu cá nhân."],en:["Run conduct assessments, scholarships, tuition waivers and allowances under the regulations.","Provide academic, wellbeing and career counseling to individuals and groups.","Build employer links, organize job fairs and manage internship programs.","Survey graduate employment and prepare reports for accreditation.","Manage student records, handle misconduct through due process and protect personal data."]},competencies:[{name:{vi:"Quy chế & chính sách",en:"Regulations & policy"},desc:{vi:"Áp dụng chính xác quy chế đào tạo, rèn luyện, học bổng và chế độ chính sách cho từng trường hợp.",en:"Apply training, conduct, scholarship and welfare regulations accurately to each case."}},{name:{vi:"Tư vấn hướng nghiệp",en:"Career counseling"},desc:{vi:"Dùng công cụ đánh giá sở thích, năng lực để giúp sinh viên tự ra quyết định nghề nghiệp.",en:"Use interest and ability assessments to help students make their own career decisions."}},{name:{vi:"Kết nối doanh nghiệp",en:"Employer engagement"},desc:{vi:"Xây dựng mạng lưới đối tác thực tập, tuyển dụng và đo lường hiệu quả hợp tác.",en:"Build a network of internship and hiring partners and measure partnership results."}},{name:{vi:"Phân tích dữ liệu người học",en:"Student data analysis"},desc:{vi:"Tổng hợp điểm, tỷ lệ việc làm, cảnh báo học vụ để phát hiện sớm sinh viên cần hỗ trợ.",en:"Combine grades, employment rates and academic warnings to identify students needing help early."}},{name:{vi:"Công bằng & bảo mật",en:"Fairness & confidentiality"},desc:{vi:"Xét duyệt khách quan, không thiên vị, không sửa kết quả đã duyệt và bảo vệ dữ liệu cá nhân.",en:"Decide objectively without favoritism, never alter approved results and protect personal data."}}],knowledge:{vi:["Luật Giáo dục đại học số 08/2012/QH13, sửa đổi bởi Luật số 34/2018/QH14.","Quy chế đào tạo trình độ đại học (Thông tư 08/2021/TT-BGDĐT): thang điểm 4 và xếp loại học lực.","Quy chế đánh giá kết quả rèn luyện của người học (Thông tư 16/2015/TT-BGDĐT): thang 100 điểm, 6 mức xếp loại.","Quy chế công tác sinh viên đối với chương trình đào tạo đại học hệ chính quy (Thông tư 10/2016/TT-BGDĐT).","Lý thuyết lựa chọn nghề của Holland (RIASEC) và lý thuyết phát triển nghề nghiệp suốt đời của Super.","Nghị định 13/2023/NĐ-CP và pháp luật hiện hành về bảo vệ dữ liệu cá nhân của người học."],en:["Higher Education Law No. 08/2012/QH13, amended by Law No. 34/2018/QH14.","Undergraduate training regulation (Circular 08/2021/TT-BGDDT): 4-point scale and academic standing.","Regulation on learner conduct assessment (Circular 16/2015/TT-BGDDT): 100-point scale with 6 bands.","Regulation on student affairs for full-time undergraduate programs (Circular 10/2016/TT-BGDDT).","Holland's career choice theory (RIASEC) and Super's life-span career development theory.","Decree 13/2023/ND-CP and current law on protecting learners' personal data."]},tools:["Phần mềm quản lý sinh viên","Trắc nghiệm sở thích nghề nghiệp RIASEC","Cổng việc làm và thực tập của trường","Biểu mẫu khảo sát trực tuyến","Microsoft Excel","Hệ thống quản lý quan hệ doanh nghiệp (CRM)"],kpis:{vi:["Tỷ lệ hồ sơ học bổng, chính sách xét đúng quy chế, không phải điều chỉnh sau công bố.","Tỷ lệ sinh viên có việc làm trong 12 tháng sau tốt nghiệp.","Số doanh nghiệp đối tác và vị trí thực tập được kết nối mỗi năm.","Mức độ hài lòng của sinh viên với dịch vụ tư vấn."],en:["Share of scholarship and welfare decisions correct first time with no post-publication changes.","Share of graduates employed within 12 months.","Partner employers and internship places secured each year.","Student satisfaction with counseling services."]},day:[{time:"08:00",vi:"Tiếp nhận đơn, giải đáp thắc mắc về học bổng và chế độ chính sách tại bộ phận một cửa.",en:"Receive applications and answer scholarship and welfare questions at the service desk."},{time:"09:30",vi:"Tổng hợp điểm học tập, điểm rèn luyện và lập danh sách dự kiến xét học bổng.",en:"Compile GPAs and conduct scores and draft the scholarship shortlist."},{time:"13:30",vi:"Tư vấn hướng nghiệp cá nhân, phân tích kết quả trắc nghiệm sở thích nghề nghiệp.",en:"Hold one-to-one career sessions and interpret interest inventory results."},{time:"15:00",vi:"Làm việc với doanh nghiệp đối tác về chương trình thực tập và ngày hội việc làm.",en:"Meet partner employers about internships and the upcoming job fair."},{time:"16:30",vi:"Cập nhật dữ liệu khảo sát việc làm và lưu hồ sơ theo quy định bảo mật.",en:"Update graduate survey data and file records under confidentiality rules."}],mistakes:{vi:["Xét học bổng chỉ theo điểm học tập, bỏ qua điều kiện điểm rèn luyện.","Chia sẻ danh sách sinh viên kèm số điện thoại cho doanh nghiệp khi chưa có sự đồng ý.","Tư vấn áp đặt theo ngành “hot” thay vì dựa trên sở thích và năng lực của sinh viên."],en:["Awarding scholarships on GPA alone and ignoring the conduct score condition.","Sharing student lists with phone numbers with employers without consent.","Pushing trendy majors instead of building on the student's interests and abilities."]},career:[{vi:"Chuyên viên công tác sinh viên",en:"Student affairs officer"},{vi:"Chuyên viên tư vấn hướng nghiệp & quan hệ doanh nghiệp",en:"Career counselor & employer relations officer"},{vi:"Phó Trưởng phòng Công tác sinh viên",en:"Deputy Head of Student Affairs"},{vi:"Trưởng phòng Công tác sinh viên, Giám đốc Trung tâm Hướng nghiệp",en:"Head of Student Affairs, Director of Career Center"}],glossary:[{term:"Conduct score",vi:"Điểm rèn luyện: kết quả đánh giá ý thức, đạo đức và mức độ tham gia hoạt động của sinh viên theo thang 100.",en:"Assessment of a student's attitude, ethics and participation on a 100-point scale."},{term:"GPA",vi:"Điểm trung bình chung học kỳ hoặc tích lũy, thường theo thang 4 trong đào tạo tín chỉ.",en:"Semester or cumulative grade point average, usually on a 4-point scale in credit-based programs."},{term:"RIASEC",vi:"Mô hình Holland chia sở thích nghề thành 6 nhóm: Kỹ thuật, Nghiên cứu, Nghệ thuật, Xã hội, Quản lý, Nghiệp vụ.",en:"Holland's model of six interest types: Realistic, Investigative, Artistic, Social, Enterprising, Conventional."},{term:"Appeal review",vi:"Phúc khảo: thủ tục người học đề nghị xem xét lại kết quả đánh giá kèm minh chứng.",en:"The procedure for a learner to request a review of an assessment result with evidence."},{term:"Tracer study",vi:"Khảo sát theo dấu sinh viên tốt nghiệp để đo tỷ lệ có việc làm và mức độ phù hợp với ngành học.",en:"A survey that follows graduates to measure employment and fit with their field of study."}],quiz:[{q:{vi:"Theo quy chế đánh giá rèn luyện, sinh viên đạt 79 điểm được xếp loại gì?",en:"Under the conduct assessment regulation, what band is a score of 79?"},options:{vi:["Xuất sắc","Tốt","Khá","Trung bình"],en:["Excellent","Good","Fairly good","Average"]},answer:2,explain:{vi:"Xuất sắc 90-100, tốt 80 đến dưới 90, khá 65 đến dưới 80; vì vậy 79 điểm là loại khá.",en:"Excellent is 90-100, good is 80 to under 90, fairly good is 65 to under 80; so 79 is fairly good."}},{q:{vi:"Sinh viên đạt HB-B với mức mô phỏng 1700000 đồng/tháng, học kỳ 5 tháng. Tổng học bổng học kỳ là bao nhiêu?",en:"A student qualifies for HB-B at a training rate of 1700000 VND/month for a 5-month semester. What is the total?"},options:{vi:["8500000 đồng","1700000 đồng","10200000 đồng","7250000 đồng"],en:["8500000 VND","1700000 VND","10200000 VND","7250000 VND"]},answer:0,explain:{vi:"Tổng học kỳ = mức tháng x số tháng = 1700000 x 5 = 8500000 đồng.",en:"Semester total = monthly rate x months = 1700000 x 5 = 8500000 VND."}},{q:{vi:"Doanh nghiệp đối tác xin danh sách sinh viên năm cuối kèm số điện thoại để mời phỏng vấn. Bạn làm gì?",en:"A partner employer asks for a list of final-year students with phone numbers to invite them to interviews. What do you do?"},options:{vi:["Gửi ngay vì có lợi cho sinh viên","Chỉ gửi cho doanh nghiệp quen biết","Gửi danh sách nhưng xóa bớt cột điểm","Chỉ chia sẻ khi sinh viên đồng ý hoặc đăng tin để sinh viên tự ứng tuyển"],en:["Send it at once as it helps students","Send it only to familiar employers","Send it with the grade column removed","Share only with student consent or post the vacancy for students to apply"]},answer:3,explain:{vi:"Số điện thoại là dữ liệu cá nhân; chỉ chia sẻ khi có sự đồng ý hoặc để sinh viên chủ động ứng tuyển.",en:"Phone numbers are personal data; share only with consent or let students apply themselves."}},{q:{vi:"Mô hình RIASEC của Holland được dùng để làm gì trong hướng nghiệp?",en:"What is Holland's RIASEC model used for in career guidance?"},options:{vi:["Tính điểm rèn luyện","Xác định nhóm sở thích nghề nghiệp để gợi ý ngành, việc làm phù hợp","Xếp loại học bổng","Đo chỉ số IQ"],en:["Calculating conduct scores","Identifying interest types to suggest suitable fields and jobs","Ranking scholarships","Measuring IQ"]},answer:1,explain:{vi:"RIASEC mô tả 6 nhóm sở thích nghề, giúp đối chiếu cá nhân với môi trường nghề nghiệp phù hợp.",en:"RIASEC describes six interest types that help match a person with suitable work environments."}}],tools_en:["Student information system","RIASEC career interest inventory","University jobs and internships portal","Online survey forms","Microsoft Excel","Employer relationship management system (CRM)"]}}})})(window.KKR);
